/* ============================================================
   ÚLTIMA LUZ — estilos
   ============================================================ */
:root{
  --amber:#ffb545;
  --amber-hot:#ff8a1f;
  --amber-soft:rgba(255,181,69,.16);
  --red:#ff4d4d;
  --red-soft:rgba(255,77,77,.16);
  --green:#9cff6e;
  --cyan:#7fe4ff;
  --ink:#05070b;
  --panel:rgba(7,11,16,.66);
  --panel-solid:#0a0f15;
  --line:rgba(255,255,255,.10);
  --line-soft:rgba(255,255,255,.055);
  --text:#eef2f4;
  --muted:#93a0a8;
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-t:env(safe-area-inset-top,0px);
  --font-ui:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --font-display:Impact,Haettenschweiler,"Arial Narrow Bold","Franklin Gothic Condensed",sans-serif;
}

*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{
  margin:0;padding:0;height:100%;overflow:hidden;background:var(--ink);
  color:var(--text);font-family:var(--font-ui);
  overscroll-behavior:none;touch-action:none;
  -webkit-user-select:none;user-select:none;
}
body{position:fixed;inset:0}

canvas#game{
  position:fixed;inset:0;width:100%;height:100%;display:block;
  background:#05070b;touch-action:none;
}
body.playing #game{cursor:none}
body.playing.using-touch #game{cursor:default}

.hidden{display:none !important}

/* overlays de ambiente */
#vignette{
  position:fixed;inset:0;pointer-events:none;z-index:5;
  background:
    radial-gradient(120% 90% at 50% 45%,transparent 42%,rgba(0,0,0,.38) 78%,rgba(0,0,0,.82) 100%),
    linear-gradient(180deg,rgba(0,0,0,.28),transparent 18%,transparent 82%,rgba(0,0,0,.42));
}
#damage-flash{
  position:fixed;inset:0;pointer-events:none;z-index:6;opacity:0;
  box-shadow:inset 0 0 140px 30px rgba(255,20,20,.55),inset 0 0 40px rgba(255,0,0,.35);
  transition:opacity .14s ease-out;
  background:radial-gradient(circle at 50% 50%,transparent 45%,rgba(120,0,0,.28) 100%);
}
#grain{
  position:fixed;inset:-20%;pointer-events:none;z-index:7;opacity:.055;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='2' stitchTiles='stitch'/></filter><rect width='160' height='160' filter='url(%23n)' opacity='.6'/></svg>");
  background-size:180px 180px;mix-blend-mode:overlay;
  animation:grainShift .55s steps(2) infinite;
}
@keyframes grainShift{
  0%{transform:translate3d(0,0,0)}25%{transform:translate3d(-2%,1%,0)}
  50%{transform:translate3d(1%,-2%,0)}75%{transform:translate3d(-1%,-1%,0)}100%{transform:translate3d(0,0,0)}
}

/* ============================ HUD ============================ */
#hud{
  position:fixed;inset:0;z-index:20;pointer-events:none;
  padding:calc(14px + var(--safe-t)) calc(16px + var(--safe-r)) calc(14px + var(--safe-b)) calc(16px + var(--safe-l));
  display:flex;flex-direction:column;justify-content:space-between;
}
.hud-top{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;position:relative}
.hud-left{width:min(340px,30vw);display:flex;flex-direction:column;gap:9px;padding:12px 14px 13px}
.panel{
  background:linear-gradient(180deg,rgba(10,15,21,.72),rgba(5,8,12,.58));
  border:1px solid var(--line);border-radius:4px;
  box-shadow:0 12px 34px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.045);
  backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);
  position:relative;
}
.panel::before,.panel::after{
  content:"";position:absolute;width:7px;height:7px;border:1px solid rgba(255,181,69,.5);pointer-events:none;
}
.panel::before{left:-1px;top:-1px;border-right:0;border-bottom:0}
.panel::after{right:-1px;bottom:-1px;border-left:0;border-top:0}

.level-row{display:flex;align-items:center;gap:11px}
.level-badge{
  flex:0 0 auto;width:46px;height:46px;border-radius:3px;
  display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1;
  background:linear-gradient(160deg,rgba(255,181,69,.18),rgba(255,138,31,.05));
  border:1px solid rgba(255,181,69,.35);
  box-shadow:inset 0 0 18px rgba(255,150,40,.08);
}
.level-badge span{font-size:8px;letter-spacing:.14em;color:#e5b978;font-weight:700}
.level-badge b{font-family:var(--font-display);font-size:24px;font-weight:400;color:#ffd79a;letter-spacing:.02em;margin-top:2px}
.xp-wrap{flex:1;min-width:0}
.bar-label{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:9px;letter-spacing:.14em;color:var(--muted);font-weight:700;margin-bottom:4px;text-transform:uppercase}
.bar-label b{color:#e9eef0;font-size:10px;letter-spacing:.06em}
.bar-label .ico{color:var(--amber);font-size:11px}
.bar{height:5px;background:rgba(255,255,255,.075);border-radius:1px;overflow:hidden;position:relative}
.bar i{display:block;height:100%;width:100%;transform-origin:left center;transition:width .12s linear;border-radius:1px}
.bar.xp i{background:linear-gradient(90deg,#b57a17,var(--amber));box-shadow:0 0 10px rgba(255,181,69,.5)}
.bar.hp{height:8px;background:rgba(255,255,255,.07)}
.bar.hp i{background:linear-gradient(90deg,#b32626,#ff5b3d 70%,#ff9d5c);box-shadow:0 0 12px rgba(255,70,40,.45)}
.bar.dash i{background:linear-gradient(90deg,#247a92,#6fd9f2);box-shadow:0 0 10px rgba(90,210,240,.4)}
.vital{display:flex;flex-direction:column}
.vitals{display:flex;flex-direction:column;gap:7px;margin-top:2px}

.wave-wrap{position:absolute;left:50%;top:2px;transform:translateX(-50%);text-align:center;pointer-events:none;min-width:220px}
.wave-kicker{font-size:8px;letter-spacing:.34em;color:rgba(255,181,69,.8);font-weight:800}
.wave-num{
  font-family:var(--font-display);font-size:clamp(22px,2.6vw,36px);letter-spacing:.06em;line-height:1;
  color:#f4f7f7;text-shadow:0 2px 18px rgba(0,0,0,.7),0 0 26px rgba(255,160,60,.16);margin-top:3px;
}
.wave-status{font-size:9px;letter-spacing:.18em;color:var(--muted);margin-top:5px;font-weight:700;text-transform:uppercase}
.wave-status b{color:var(--amber)}

.hud-right{display:flex;align-items:flex-start;gap:9px}
.score-panel{padding:9px 13px;min-width:176px}
.score-line{display:flex;align-items:baseline;justify-content:space-between;gap:14px}
.score-line span{font-size:8px;letter-spacing:.2em;color:var(--muted);font-weight:800}
.score-line b{font-family:var(--font-display);font-size:24px;font-weight:400;letter-spacing:.04em;color:#fff;line-height:1}
.score-sub{display:flex;justify-content:space-between;gap:12px;margin-top:4px;font-size:8px;letter-spacing:.13em;color:#75838b;font-weight:700}
.score-sub b{color:#c9d3d7;letter-spacing:.04em}
.sys-buttons{display:flex;flex-direction:column;gap:6px}
.icon-btn{
  width:34px;height:34px;padding:0;display:grid;place-items:center;cursor:pointer;
  background:rgba(8,12,17,.7);border:1px solid var(--line);border-radius:3px;color:#b8c3c8;
  backdrop-filter:blur(6px);transition:.15s ease;pointer-events:auto;
}
.icon-btn:hover{color:var(--amber);border-color:rgba(255,181,69,.45);background:rgba(20,17,11,.8)}
.icon-btn svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.icon-btn .ic-on{display:none}
body.sound-on .icon-btn .ic-on{display:block}
body.sound-on .icon-btn .ic-off{display:none}
#btn-mute{color:#7c8a91}
body.sound-on #btn-mute{color:#c9d3d7}

#boss-wrap{
  position:absolute;left:50%;top:calc(88px + var(--safe-t));transform:translateX(-50%);
  width:min(520px,62vw);text-align:center;pointer-events:none;
}
.boss-name{font-size:9px;letter-spacing:.3em;color:#ff8b7a;font-weight:800;margin-bottom:5px}
.boss-name span{color:#8d6b68;font-size:8px;letter-spacing:.2em;margin-right:6px}
.bar.boss{height:7px;background:rgba(255,255,255,.07);border:1px solid rgba(255,80,60,.22)}
.bar.boss i{background:linear-gradient(90deg,#7c0f0f,#ff3b2e 55%,#ff7b4d);box-shadow:0 0 14px rgba(255,50,30,.5);transition:width .12s linear}

#toast{
  position:absolute;left:50%;top:calc(128px + var(--safe-t));transform:translate(-50%,-8px);
  font-family:var(--font-display);font-size:clamp(20px,2.4vw,32px);letter-spacing:.1em;
  color:#fff;text-shadow:0 2px 20px rgba(0,0,0,.8),0 0 30px rgba(255,160,60,.25);
  opacity:0;transition:opacity .18s ease,transform .18s ease;pointer-events:none;text-align:center;white-space:nowrap;
}
#toast.show{opacity:1;transform:translate(-50%,0)}
#toast.danger{color:#ff8a7a;text-shadow:0 2px 20px rgba(0,0,0,.85),0 0 34px rgba(255,50,30,.5)}
#toast.good{color:#d8ffb8;text-shadow:0 2px 20px rgba(0,0,0,.85),0 0 30px rgba(120,255,80,.3)}

.hud-bottom{display:flex;align-items:flex-end;justify-content:space-between;gap:16px}
.hud-hint{
  display:flex;gap:15px;align-items:center;padding:8px 12px;font-size:8px;letter-spacing:.12em;
  color:#85939a;font-weight:700;opacity:.82;transition:opacity .4s ease;
}
.hud-hint span{display:flex;align-items:center;gap:5px;white-space:nowrap}
kbd{
  font-family:var(--font-ui);font-size:9px;font-weight:800;letter-spacing:.05em;
  color:#d7dfe2;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);
  border-bottom-color:rgba(0,0,0,.5);border-radius:2px;padding:2px 5px;line-height:1.2;
}
.weapon-panel{padding:10px 13px 11px;min-width:196px;pointer-events:auto}
.weapon-slots{display:flex;gap:4px;margin-bottom:7px}
.weapon-slot{
  flex:1;height:18px;display:grid;place-items:center;cursor:pointer;
  border:1px solid rgba(255,255,255,.08);border-radius:2px;background:rgba(255,255,255,.025);
  font-size:8px;font-weight:800;letter-spacing:.08em;color:#66747b;transition:.12s ease;
}
.weapon-slot:hover{color:#c3ced2;border-color:rgba(255,255,255,.18)}
.weapon-slot.active{color:#1a1206;background:linear-gradient(180deg,#ffc76b,#f09a2a);border-color:#ffc76b;box-shadow:0 0 14px rgba(255,170,50,.28)}
.weapon-slot.empty{opacity:.45}
.weapon-main{display:flex;align-items:flex-end;justify-content:space-between;gap:12px}
.weapon-name{font-size:9px;letter-spacing:.2em;color:#93a1a8;font-weight:800;padding-bottom:4px}
.ammo{display:flex;align-items:baseline;gap:4px;line-height:1}
.ammo b{font-family:var(--font-display);font-size:30px;font-weight:400;letter-spacing:.02em;color:#fff;text-shadow:0 0 18px rgba(255,180,80,.18)}
.ammo span{font-size:12px;color:#8c9aa1;font-weight:700;letter-spacing:.04em}
.weapon-panel.low .ammo b{color:#ff6b5a}
.bar.reload{height:3px;margin-top:7px;background:rgba(255,255,255,.08)}
.bar.reload i{background:linear-gradient(90deg,#ffb545,#ffe1a3);box-shadow:0 0 10px rgba(255,181,69,.5);transition:width .05s linear}
.buff{
  position:absolute;left:50%;bottom:calc(84px + var(--safe-b));transform:translateX(-50%);
  padding:6px 12px;border:1px solid rgba(255,181,69,.4);border-radius:2px;
  background:rgba(28,18,6,.6);backdrop-filter:blur(6px);
  font-size:9px;letter-spacing:.18em;color:#ffce85;font-weight:800;
  display:flex;align-items:center;gap:8px;box-shadow:0 0 22px rgba(255,160,50,.15);
}
.buff b{font-family:var(--font-display);font-size:15px;letter-spacing:.06em;color:#fff;font-weight:400}
#hud.low-hp .bar.hp i{animation:hpPulse .65s ease-in-out infinite alternate}
@keyframes hpPulse{from{filter:brightness(1)}to{filter:brightness(1.7);box-shadow:0 0 18px rgba(255,40,20,.8)}}

/* ============================ TÁCTIL ============================ */
#touch-ui{position:fixed;inset:0;z-index:25;pointer-events:none}
.stick{
  position:absolute;width:132px;height:132px;border-radius:50%;
  pointer-events:auto;touch-action:none;
  background:radial-gradient(circle at 50% 50%,rgba(255,255,255,.035),rgba(0,0,0,.08) 70%,transparent 72%);
  border:1px solid rgba(255,255,255,.13);
  box-shadow:inset 0 0 30px rgba(0,0,0,.25);
  transition:border-color .15s ease,background .15s ease;
}
.stick.active{border-color:rgba(255,181,69,.4);background:radial-gradient(circle at 50% 50%,rgba(255,181,69,.08),rgba(0,0,0,.1) 70%,transparent 72%)}
#stick-move{left:calc(18px + var(--safe-l));bottom:calc(20px + var(--safe-b))}
#stick-aim{right:calc(18px + var(--safe-r));bottom:calc(20px + var(--safe-b))}
#stick-aim{border-color:rgba(127,228,255,.18)}
#stick-aim.active{border-color:rgba(127,228,255,.45);background:radial-gradient(circle at 50% 50%,rgba(127,228,255,.08),rgba(0,0,0,.1) 70%,transparent 72%)}
.stick-ring{position:absolute;inset:24px;border-radius:50%;border:1px dashed rgba(255,255,255,.08)}
.stick-knob{
  position:absolute;left:50%;top:50%;width:56px;height:56px;border-radius:50%;
  transform:translate(-50%,-50%);
  background:radial-gradient(circle at 38% 32%,rgba(255,255,255,.32),rgba(255,181,69,.28) 45%,rgba(255,138,31,.12));
  border:1px solid rgba(255,181,69,.55);
  box-shadow:0 4px 16px rgba(0,0,0,.4),0 0 22px rgba(255,170,60,.16);
  transition:transform .08s ease-out;
  will-change:transform;
}
#stick-aim .stick-knob{
  background:radial-gradient(circle at 38% 32%,rgba(255,255,255,.3),rgba(127,228,255,.24) 45%,rgba(60,160,200,.1));
  border-color:rgba(127,228,255,.5);box-shadow:0 4px 16px rgba(0,0,0,.4),0 0 22px rgba(100,210,255,.16);
}
.stick-tag{position:absolute;left:50%;bottom:-17px;transform:translateX(-50%);font-size:8px;letter-spacing:.24em;color:rgba(255,255,255,.32);font-weight:800}
.touch-buttons{
  position:absolute;right:calc(24px + var(--safe-r));bottom:calc(172px + var(--safe-b));
  display:flex;align-items:flex-end;gap:11px;pointer-events:none;
}
.touch-btn{
  pointer-events:auto;touch-action:none;border-radius:50%;
  display:grid;place-items:center;padding:0;cursor:pointer;
  background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.14),rgba(10,14,18,.72));
  border:1px solid rgba(255,255,255,.18);color:#dbe3e6;
  box-shadow:0 6px 20px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.1);
  transition:transform .1s ease,background .15s ease,border-color .15s ease;
}
.touch-btn:active{transform:scale(.92);background:rgba(255,181,69,.24);border-color:rgba(255,181,69,.6)}
.touch-btn svg{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.touch-btn.small{width:50px;height:50px}
.touch-btn.dash-btn{width:66px;height:66px;color:#ffd48c;border-color:rgba(255,181,69,.4);background:radial-gradient(circle at 35% 30%,rgba(255,200,100,.2),rgba(20,14,6,.72))}
.touch-btn.dash-btn.cooling{opacity:.4}
.touch-btn.dash-btn svg{width:30px;height:30px}

/* ============================ PANTALLAS ============================ */
#screens{position:fixed;inset:0;z-index:40;pointer-events:none}
.screen{
  position:absolute;inset:0;display:none;flex-direction:column;
  pointer-events:auto;
}
.screen.active{display:flex}

/* --- título --- */
#screen-title{
  justify-content:space-between;align-items:center;text-align:center;
  padding:calc(26px + var(--safe-t)) calc(24px + var(--safe-r)) calc(22px + var(--safe-b)) calc(24px + var(--safe-l));
  background:
    radial-gradient(90% 70% at 50% 30%,transparent 20%,rgba(3,5,8,.28) 66%,rgba(3,5,8,.86) 100%),
    linear-gradient(180deg,rgba(3,6,10,.38) 0%,transparent 30%,transparent 55%,rgba(3,5,8,.9) 100%);
}
.title-top{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:min(6vh,54px)}
.eyebrow{
  display:flex;align-items:center;gap:12px;
  font-size:clamp(8px,.85vw,11px);letter-spacing:.42em;color:#c7a97a;font-weight:800;
  text-shadow:0 2px 12px rgba(0,0,0,.9);
}
.eyebrow i{display:block;width:clamp(24px,4vw,58px);height:1px;background:linear-gradient(90deg,transparent,rgba(255,181,69,.7));}
.eyebrow i:last-child{transform:scaleX(-1)}
.logo{
  margin:0;font-family:var(--font-display);font-weight:400;
  font-size:clamp(64px,12.5vw,178px);line-height:.82;letter-spacing:.015em;
  display:flex;gap:.08em;align-items:baseline;justify-content:center;
  filter:drop-shadow(0 8px 30px rgba(0,0,0,.8));
}
.logo .l1{
  color:#f2f6f5;
  background:linear-gradient(180deg,#ffffff 0%,#e7eef0 42%,#9aa8ac 70%,#e9f0f1 100%);
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
  text-shadow:0 0 40px rgba(190,220,230,.08);
}
.logo .l2{
  color:var(--amber);
  background:linear-gradient(180deg,#ffe6b0 0%,#ffb545 38%,#ff7a16 72%,#c84b06 100%);
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
  text-shadow:0 0 60px rgba(255,140,30,.32);
  animation:logoFlicker 7s infinite;
}
@keyframes logoFlicker{
  0%,91%,94%,100%{opacity:1;filter:drop-shadow(0 0 26px rgba(255,150,40,.24))}
  92%{opacity:.72;filter:drop-shadow(0 0 8px rgba(255,150,40,.1))}
  93%{opacity:.94}
  95%{opacity:.83}
}
.tagline{
  margin:2px 0 0;font-size:clamp(11px,1.1vw,14px);line-height:1.65;letter-spacing:.12em;
  color:#a8b4b8;text-transform:uppercase;text-shadow:0 2px 16px rgba(0,0,0,.9);
}
.tagline b{color:#e6edee;font-weight:700}

.title-panel{
  width:min(600px,92vw);display:flex;flex-direction:column;align-items:center;gap:13px;
  padding:clamp(16px,2.4vh,26px) clamp(18px,3vw,34px);
  background:linear-gradient(180deg,rgba(9,13,18,.72),rgba(5,8,11,.62));
  border:1px solid rgba(255,255,255,.11);border-radius:4px;
  box-shadow:0 30px 80px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.05);
  backdrop-filter:blur(9px);-webkit-backdrop-filter:blur(9px);
  position:relative;
}
.title-panel::before,.title-panel::after{
  content:"";position:absolute;width:12px;height:12px;border:1px solid rgba(255,181,69,.55);
}
.title-panel::before{left:-1px;top:-1px;border-right:0;border-bottom:0}
.title-panel::after{right:-1px;bottom:-1px;border-left:0;border-top:0}
.btn{
  position:relative;border:0;cursor:pointer;font-family:var(--font-ui);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;
  transition:transform .13s ease,box-shadow .18s ease,background .18s ease,color .18s ease;
}
.btn:active{transform:translateY(1px) scale(.995)}
.btn.primary{
  width:min(360px,100%);min-height:62px;padding:12px 30px;
  background:linear-gradient(180deg,#ffcf7a 0%,#ffb545 44%,#ee8a1c 100%);
  color:#1b1104;border-radius:3px;
  box-shadow:0 8px 30px rgba(255,140,20,.24),inset 0 1px 0 rgba(255,255,255,.6),inset 0 -2px 0 rgba(120,50,0,.3);
  clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px);
}
.btn.primary span{font-family:var(--font-display);font-size:clamp(22px,2.2vw,28px);letter-spacing:.1em;line-height:1}
.btn.primary small{font-size:8px;letter-spacing:.26em;font-weight:800;opacity:.62}
.btn.primary:hover{background:linear-gradient(180deg,#ffe0a2,#ffc05f 44%,#ff9a2d);box-shadow:0 10px 40px rgba(255,150,30,.4),inset 0 1px 0 rgba(255,255,255,.7)}
.btn.ghost{
  min-height:40px;padding:9px 20px;font-size:10px;letter-spacing:.2em;font-weight:800;
  color:#c3ced2;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.14);border-radius:3px;
}
.btn.ghost:hover{color:#fff;border-color:rgba(255,181,69,.45);background:rgba(255,181,69,.08)}
.best-line{display:flex;align-items:center;gap:12px;font-size:8px;letter-spacing:.24em;color:#7c898f;font-weight:800}
.best-line b{font-family:var(--font-display);font-size:18px;font-weight:400;letter-spacing:.06em;color:#ffd08a}
.controls-grid{
  display:grid;grid-template-columns:repeat(3,1fr);gap:6px 16px;width:100%;
  padding-top:11px;border-top:1px solid rgba(255,255,255,.07);
}
