Let me write Audio with careful scheduling.

```js
const Sound = {
 ctx:null, master:null, muted:false, noiseBuf:null, started:false,
 init(){
   if(this.ctx){ if(this.ctx.state==='suspended') this.ctx.resume(); return; }
   const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return;
   const c=this.ctx=new AC();
   const comp=c.createDynamicsCompressor();
   comp.threshold.value=-18; comp.knee.value=20; comp.ratio.value=6; comp.attack.value=0.003; comp.release.value=0.25;
   comp.connect(c.destination);
   this.master=c.createGain(); this.master.gain.value=this.muted?0:0.55; this.master.connect(comp);
   // noise buffer
   const len=c.sampleRate*1.2; const buf=c.createBuffer(1,len,c.sampleRate); const d=buf.getChannelData(0);
   for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
   this.noiseBuf=buf;
   this.ambient();
   this.started=true;
 },
 setMuted(m){...}
```
Mute toggles: master gain set with setTargetAtTime.

Noise source helper:
```js
_noise(dur, vol, type, freq, q, when=0, pan=0){
 const c=this.ctx; if(!c) return;
 const src=c.createBufferSource(); src.buffer=this.noiseBuf; src.loop=true;
 const f=c.createBiquadFilter(); f.type=type; f.frequency.value=freq; f.Q.value=q;
 const g=c.createGain(); const t=c.currentTime+when;
 g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(vol,t+0.005); g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
 const p=c.createStereoPanner? c.createStereoPanner():null; if(p)p.pan.value=pan;
 src.connect(f); f.connect(g); if(p){g.connect(p);p.connect(this.master);} else g.connect(this.master);
 src.start(t); src.stop(t+dur+0.02);
}
```
Note: exponential ramp from 0.0001 okay.

