```js
ambient(){
 const c=this.ctx;
 const g=c.createGain(); g.gain.value=0.0; g.gain.setTargetAtTime(0.05, c.currentTime, 2); g.connect(this.master);
 // low drone
 [55, 82.4, 110].forEach((f,i)=>{ const o=c.createOscillator(); o.type=i===2?'sine':'triangle'; o.frequency.value=f; const og=c.createGain(); og.gain.value=i===2?0.03:0.045; const lp=c.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=180; o.connect(og); og.connect(lp); lp.connect(g); o.start(); });
 // wind
 const src=c.createBufferSource(); src.buffer=this.noiseBuf; src.loop=true;
 const f=c.createBiquadFilter(); f.type='bandpass'; f.frequency.value=420; f.Q.value=0.6;
 const wg=c.createGain(); wg.gain.value=0.05;
 const lfo=c.createOscillator(); lfo.frequency.value=0.08; const lg=c.createGain(); lg.gain.value=0.03; lfo.connect(lg); lg.connect(wg.gain); lfo.start();
 src.connect(f); f.connect(wg); wg.connect(g); src.start();
}
