for(const s of solids){
 const nx=clamp(ent.x,s.x,s.x+s.w), ny=...
 let dx=ent.x-nx, dy=ent.y-ny;
 const d2=dx*dx+dy*dy;
 if(d2<r*r){
  if(d2>0.0001){ const d=Math.sqrt(d2); ent.x+=dx/d*(r-d); ent.y+=dy/d*(r-d); }
  else { // center inside rect: push out shortest
   const left=ent.x-s.x, right=s.x+s.w-ent.x, top=ent.y-s.y, bottom=s.y+s.h-ent.y;
   const m=Math.min(left,right,top,bottom);
   if(m===left) ent.x=s.x-r; else if(m===right) ent.x=s.x+s.w+r; else if(m===top) ent.y=s.y-r; else ent.y=s.y+s.h+r;
  }
 }
}
