113:   ctx.ellipse(0, 0, z.type === 'brute' || z.type === 'boss' ? 11 : 9.5, z.type === 'brute' || z.type === 'boss' ? 9.5 : 8, 0, 0, TAU);
114:   ctx.fill();
115:   // harapos
116:   ctx.fillStyle = 'rgba(10,10,10,.35)';
117:   for (let i = 0; i < 4; i++) {
118:     const a = Math.PI * 0.55 + i * 0.45;
119:     ctx.beginPath();
120:     ctx.moveTo(Math.cos(a) * 7, Math.sin(a) * 7);
121:     ctx.lineTo(Math.cos(a) * 11.5, Math.sin(a) * 11.5);
122:     ctx.lineTo(Math.cos(a + 0.22) * 8, Math.sin(a + 0.22) * 8);
123:     ctx.closePath();
124:     ctx.fill();
125:   }
126: 
127:   // hombreras
128:   if (z.type === 'brute' || z.type === 'boss') {
129:     ctx.fillStyle = z.type === 'boss' ? '#4a2a22' : '#332b24';
130:     ctx.beginPath(); ctx.ellipse(1, -7.5, 5, 3.2, -0.2, 0, TAU); ctx.fill();
131:     ctx.beginPath(); ctx.ellipse(1, 7.5, 5, 3.2, 0.2, 0, TAU); ctx.fill();
132:   }
133: 
134:   // saco de ácido
135:   if (z.type === 'spitter') {
136:     const puls = 1 + Math.sin(t * 6 + z.seed) * 0.12;
137:     ctx.fillStyle = 'rgba(110,180,60,.85)';
138:     ctx.beginPath(); ctx.ellipse(-3.5, 0, 5 * puls, 4.2 * puls, 0, 0, TAU); ctx.fill();
139:     ctx.fillStyle = 'rgba(190,255,120,.45)';
140:     ctx.beginPath(); ctx.ellipse(-3.5, -1, 2.2, 1.8, 0, 0, TAU); ctx.fill();
141:   }
142: 
143:   // púas del titán
144:   if (z.type === 'boss') {
145:     ctx.fillStyle = '#6e4a38';
146:     for (let i = 0; i < 5; i++) {
147:       const yy = -7 + i * 3.5;
148:       ctx.beginPath();
149:       ctx.moveTo(-7, yy);
150:       ctx.lineTo(-13, yy + 1.2);
151:       ctx.lineTo(-7.5, yy + 2.4);
152:       ctx.closePath();
153:       ctx.fill();
154:     }
155:   }
156: 
157:   // cabeza
158:   ctx.fillStyle = skin;
159:   ctx.beginPath();
160:   ctx.arc(7.2, 0, z.type === 'brute' || z.type === 'boss' ? 5.6 : 5.1, 0, TAU);
161:   ctx.fill();
162:   // pelo / costra
163:   ctx.fillStyle = 'rgba(25,22,18,.7)';
164:   ctx.beginPath();
165:   ctx.arc(5.2, 0, 5.2, Math.PI * 0.6, Math.PI * 1.4);
166:   ctx.fill();
167:   // boca
168:   ctx.fillStyle = 'rgba(80,10,10,.75)';
169:   ctx.beginPath(); ctx.arc(10.6, 0, 1.5, 0, TAU); ctx.fill();
170: 
171:   if (flash) {
172:     ctx.globalCompositeOperation = 'lighter';
173:     ctx.fillStyle = `rgba(255,235,220,${0.35 + 0.4 * (z.flash / 0.12)})`;
174:     ctx.beginPath();
175:     ctx.ellipse(0, 0, 12, 10, 0, 0, TAU);
176:     ctx.fill();
177:     ctx.globalCompositeOperation = 'source-over';
178:   }
179: 
180:   ctx.restore();
181: }
