183: function drawPlayer(t) {
184:   const p = player;
185:   if (!p) return;
186:   const w = p.weapons[p.weaponIndex];
187:   const swing = Math.sin(p.walkPhase * 2.2) * 3;
188:   const dying = game.state === 'dying' || game.state === 'gameover';
189: 
190:   ctx.save();
191:   ctx.translate(p.x, p.y);
192:   ctx.rotate(p.angle);
193:   if (dying) ctx.globalAlpha = 0.55;
194:   else if (p.invuln > 0) ctx.globalAlpha = 0.62 + 0.38 * Math.sin(t * 42);
195: 
196:   // piernas
197:   ctx.fillStyle = '#1c2730';
198:   rr(ctx, -9, -7 + swing, 12, 5, 2.5); ctx.fill();
199:   rr(ctx, -9, 2 - swing, 12, 5, 2.5); ctx.fill();
200: 
201:   // mochila
202:   ctx.fillStyle = '#2a231b';
203:   rr(ctx, -14, -6.5, 7, 13, 3); ctx.fill();
204:   ctx.strokeStyle = 'rgba(255,255,255,.06)';
205:   ctx.lineWidth = 1;
206:   ctx.beginPath(); ctx.moveTo(-12, -4); ctx.lineTo(-12, 4); ctx.stroke();
207: 
208:   // torso
209:   const tg = ctx.createLinearGradient(-8, -8, 8, 8);
210:   tg.addColorStop(0, '#4a5b66');
211:   tg.addColorStop(0.55, '#36454f');
212:   tg.addColorStop(1, '#25323b');
213:   ctx.fillStyle = tg;
214:   ctx.beginPath(); ctx.ellipse(0, 0, 10, 8.2, 0, 0, TAU); ctx.fill();
215:   ctx.strokeStyle = 'rgba(0,0,0,.35)';
216:   ctx.lineWidth = 1;
217:   ctx.stroke();
218:   // chaleco
219:   ctx.fillStyle = 'rgba(40,52,42,.75)';
220:   rr(ctx, -2, -6.2, 7, 12.4, 2); ctx.fill();
221:   ctx.strokeStyle = 'rgba(255,190,100,.25)';
222:   ctx.beginPath(); ctx.moveTo(0, -4); ctx.lineTo(0, 4); ctx.stroke();
223: 
224:   // brazos
225:   ctx.strokeStyle = '#c39a73';
226:   ctx.lineWidth = 3.2;
227:   ctx.lineCap = 'round';
228:   ctx.beginPath(); ctx.moveTo(3, -6); ctx.lineTo(12, -4); ctx.stroke();
229:   ctx.beginPath(); ctx.moveTo(3, 6); ctx.lineTo(12, 4); ctx.stroke();
230:   ctx.fillStyle = '#c39a73';
231:   ctx.beginPath(); ctx.arc(12.5, -4, 2, 0, TAU); ctx.fill();
232:   ctx.beginPath(); ctx.arc(12.5, 4, 2, 0, TAU); ctx.fill();
233: 
234:   // arma
235:   ctx.fillStyle = '#181c20';
236:   ctx.strokeStyle = 'rgba(255,255,255,.12)';
237:   ctx.lineWidth = 0.8;
238:   if (w.id === 'pistol') {
239:     rr(ctx, 9, -1.6, 11, 3.2, 1); ctx.fill(); ctx.stroke();
240:     rr(ctx, 11, 1.2, 3, 5, 1); ctx.fill();
241:   } else if (w.id === 'shotgun') {
242:     rr(ctx, 8, -2, 23, 4, 1); ctx.fill(); ctx.stroke();
243:     rr(ctx, 14, -3.4, 6, 6.8, 1.2); ctx.fill();
244:     ctx.fillStyle = '#3a2a1b';
245:     rr(ctx, 5, -2.6, 5, 5.2, 1); ctx.fill();
246:   } else if (w.id === 'smg') {
247:     rr(ctx, 8, -2, 17, 4, 1); ctx.fill(); ctx.stroke();
248:     rr(ctx, 13, 1.4, 4, 7, 1); ctx.fill();
249:     rr(ctx, 18, -2.8, 4, 1.8, 0.8); ctx.fill();
250:   } else {
251:     rr(ctx, 7, -1.6, 26, 3.2, 1); ctx.fill(); ctx.stroke();
252:     rr(ctx, 15, -4.2, 8, 2.2, 1); ctx.fill();
253:     rr(ctx, 11, 1.2, 4, 6, 1); ctx.fill();
254:   }
255: 
256:   // cabeza
257:   ctx.fillStyle = '#caa078';
258:   ctx.beginPath(); ctx.arc(5, 0, 5, 0, TAU); ctx.fill();
259:   // gorra
260:   ctx.fillStyle = '#39463b';
261:   ctx.beginPath(); ctx.arc(4.3, 0, 5.05, Math.PI * 0.55, Math.PI * 1.45); ctx.fill();
262:   ctx.fillStyle = '#2c372e';
263:   rr(ctx, 5, -4.6, 4.4, 9.2, 1.4); ctx.fill();
264:   // pelo / nuca
265:   ctx.fillStyle = 'rgba(30,22,16,.8)';
266:   ctx.beginPath(); ctx.arc(2.2, 0, 4.6, Math.PI * 0.55, Math.PI * 1.45); ctx.fill();
267: 
268:   if (p.flash > 0) {
269:     ctx.globalCompositeOperation = 'lighter';
270:     ctx.fillStyle = `rgba(255,90,70,${p.flash * 3})`;
271:     ctx.beginPath(); ctx.arc(0, 0, 15, 0, TAU); ctx.fill();
272:     ctx.globalCompositeOperation = 'source-over';
273:   }
274: 
275:   ctx.restore();
276: }
