290:       ctx.beginPath();
291:       ctx.moveTo(0, -5.5); ctx.lineTo(4.2, 0); ctx.lineTo(0, 5.5); ctx.lineTo(-4.2, 0);
292:       ctx.closePath(); ctx.fill();
293:       ctx.shadowBlur = 0;
294:       ctx.fillStyle = 'rgba(240,255,220,.8)';
295:       ctx.beginPath();
296:       ctx.moveTo(0, -2.6); ctx.lineTo(1.8, 0); ctx.lineTo(0, 2.6); ctx.lineTo(-1.8, 0);
297:       ctx.closePath(); ctx.fill();
298:     } else if (pu.type === 'medkit') {
299:       ctx.fillStyle = 'rgba(225,232,228,.95)';
300:       rr(ctx, -8, -6.5, 16, 13, 2); ctx.fill();
301:       ctx.fillStyle = '#d6423a';
302:       ctx.fillRect(-1.8, -4.4, 3.6, 8.8);
303:       ctx.fillRect(-4.4, -1.8, 8.8, 3.6);
304:       ctx.strokeStyle = 'rgba(0,0,0,.3)'; ctx.lineWidth = 1;
305:       rr(ctx, -8, -6.5, 16, 13, 2); ctx.stroke();
306:     } else if (pu.type === 'ammo') {
307:       ctx.fillStyle = '#56603c';
308:       rr(ctx, -9, -6, 18, 12, 2); ctx.fill();
309:       ctx.fillStyle = '#8d9a5c';
310:       ctx.fillRect(-9, -6, 18, 3);
311:       ctx.fillStyle = '#d9b356';
312:       for (let i = -2; i <= 2; i++) ctx.fillRect(i * 3 - 1, -2, 2, 6);
313:       ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 1;
314:       rr(ctx, -9, -6, 18, 12, 2); ctx.stroke();
315:     } else {
316:       ctx.rotate(-0.65);
317:       ctx.fillStyle = '#ffcf6b';
318:       rr(ctx, -2.4, -8, 4.8, 12, 1.5); ctx.fill();
319:       ctx.fillStyle = '#9aa6ac';
320:       ctx.fillRect(-0.8, 4, 1.6, 6);
321:       ctx.fillStyle = '#d9e0e3';
322:       ctx.fillRect(-3.6, -10, 7.2, 2.4);
323:       ctx.fillStyle = 'rgba(255,255,255,.55)';
324:       ctx.fillRect(-1.4, -6, 1.2, 7);
325:     }
326:     ctx.restore();
327:   }
