348: function drawParticles() {
349:   for (const p of particles) {
350:     const a = clamp(p.life / p.max, 0, 1);
351:     if (p.type === 'spark') {
352:       ctx.strokeStyle = `rgba(${p.color},${a})`;
353:       ctx.lineWidth = p.size;
354:       ctx.beginPath();
355:       ctx.moveTo(p.x, p.y);
356:       ctx.lineTo(p.x - p.vx * 0.02, p.y - p.vy * 0.02);
357:       ctx.stroke();
358:     } else if (p.type === 'smoke' || p.type === 'dust') {
359:       ctx.fillStyle = `rgba(${p.color},${a * (p.type === 'smoke' ? 0.2 : 0.24)})`;
360:       ctx.beginPath();
361:       ctx.arc(p.x, p.y, p.size * (1 + (1 - a) * 1.8), 0, TAU);
362:       ctx.fill();
363:     } else if (p.type === 'shell') {
364:       ctx.save();
365:       ctx.translate(p.x, p.y);
366:       ctx.rotate(p.rot);
367:       ctx.fillStyle = `rgba(${p.color},${a})`;
368:       ctx.fillRect(-1.5, -0.8, 3, 1.6);
369:       ctx.restore();
370:     } else if (p.type === 'acid') {
371:       ctx.fillStyle = `rgba(${p.color},${a})`;
372:       ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, TAU); ctx.fill();
373:     } else {
374:       ctx.fillStyle = `rgba(${p.color},${a * 0.85})`;
375:       ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, TAU); ctx.fill();
376:     }
377:   }
378: }
