383: function drawLighting(cx, cy, t) {
384:   const px = sxOf(player.x, cx);
385:   const py = syOf(player.y, cy);
386: 
387:   lctx.setTransform(1, 0, 0, 1, 0, 0);
388:   lctx.clearRect(0, 0, W, H);
389:   lctx.fillStyle = 'rgba(3,6,12,.76)';
390:   lctx.fillRect(0, 0, W, H);
391:   lctx.globalCompositeOperation = 'destination-out';
392: 
393:   // luz ambiental del jugador
394:   const ambR = 235 * zoom;
395:   let g = lctx.createRadialGradient(px, py, 12, px, py, ambR);
396:   g.addColorStop(0, 'rgba(0,0,0,.95)');
397:   g.addColorStop(0.55, 'rgba(0,0,0,.52)');
398:   g.addColorStop(1, 'rgba(0,0,0,0)');
399:   lctx.fillStyle = g;
400:   lctx.beginPath(); lctx.arc(px, py, ambR, 0, TAU); lctx.fill();
401: 
402:   // linterna
403:   const dist = 660 * zoom;
404:   for (let i = 0; i < 5; i++) {
405:     const spread = 0.56 - i * 0.062;
406:     const cg = lctx.createRadialGradient(px, py, 18, px, py, dist);
407:     cg.addColorStop(0, 'rgba(0,0,0,.3)');
408:     cg.addColorStop(0.45, 'rgba(0,0,0,.26)');
409:     cg.addColorStop(0.82, 'rgba(0,0,0,.14)');
410:     cg.addColorStop(1, 'rgba(0,0,0,0)');
411:     lctx.fillStyle = cg;
412:     lctx.beginPath();
413:     lctx.moveTo(px, py);
414:     lctx.arc(px, py, dist, player.angle - spread, player.angle + spread);
415:     lctx.closePath();
416:     lctx.fill();
417:   }
418: 
419:   // farolas
420:   for (const l of lampLights) {
421:     const lx = sxOf(l.x, cx), ly = syOf(l.y, cy);
422:     if (lx < -220 || lx > W + 220 || ly < -220 || ly > H + 220) continue;
423:     const flick = 0.78 + Math.sin(t * 8 + l.seed) * 0.09 + Math.sin(t * 27 + l.seed * 4) * 0.06;
424:     const r = l.r * zoom;
425:     const lg = lctx.createRadialGradient(lx, ly, 4, lx, ly, r);
426:     lg.addColorStop(0, `rgba(0,0,0,${0.62 * flick})`);
427:     lg.addColorStop(0.55, `rgba(0,0,0,${0.28 * flick})`);
428:     lg.addColorStop(1, 'rgba(0,0,0,0)');
429:     lctx.fillStyle = lg;
430:     lctx.beginPath(); lctx.arc(lx, ly, r, 0, TAU); lctx.fill();
431:   }
432: 
433:   // fuegos
434:   for (const f of fireLights) {
435:     const fx = sxOf(f.x, cx), fy = syOf(f.y, cy);
436:     if (fx < -180 || fx > W + 180 || fy < -180 || fy > H + 180) continue;
437:     const flick = 0.8 + Math.sin(t * 17 + f.seed) * 0.16 + Math.sin(t * 41 + f.seed * 2) * 0.08;
438:     const r = f.r * zoom;
439:     const fg = lctx.createRadialGradient(fx, fy, 4, fx, fy, r);
440:     fg.addColorStop(0, `rgba(0,0,0,${0.6 * flick})`);
441:     fg.addColorStop(0.6, `rgba(0,0,0,${0.25 * flick})`);
442:     fg.addColorStop(1, 'rgba(0,0,0,0)');
443:     lctx.fillStyle = fg;
444:     lctx.beginPath(); lctx.arc(fx, fy, r, 0, TAU); lctx.fill();
445:   }
446: 
447:   // fogonazos
448:   for (const f of flashes) {
449:     const fx = sxOf(f.x, cx), fy = syOf(f.y, cy);
450:     const a = clamp(f.life / f.max, 0, 1);
451:     const r = f.size * 4.2 * zoom;
452:     const fg = lctx.createRadialGradient(fx, fy, 0, fx, fy, r);
453:     fg.addColorStop(0, `rgba(0,0,0,${0.9 * a})`);
454:     fg.addColorStop(1, 'rgba(0,0,0,0)');
455:     lctx.fillStyle = fg;
456:     lctx.beginPath(); lctx.arc(fx, fy, r, 0, TAU); lctx.fill();
457:   }
458: 
459:   lctx.globalCompositeOperation = 'source-over';
460:   ctx.drawImage(lightCanvas, 0, 0, W, H);
461: 
462:   // tintes cálidos y brillos aditivos
463:   ctx.save();
464:   ctx.globalCompositeOperation = 'lighter';
465: 
466:   for (const l of lampLights) {
467:     const lx = sxOf(l.x, cx), ly = syOf(l.y, cy);
468:     if (lx < -160 || lx > W + 160 || ly < -160 || ly > H + 160) continue;
469:     const flick = 0.8 + Math.sin(t * 8 + l.seed) * 0.1 + Math.sin(t * 27 + l.seed * 4) * 0.06;
470:     const r = l.r * 1.05 * zoom;
471:     const lg = ctx.createRadialGradient(lx, ly, 0, lx, ly, r);
472:     lg.addColorStop(0, `rgba(255,184,96,${0.13 * flick})`);
473:     lg.addColorStop(0.45, `rgba(255,150,60,${0.05 * flick})`);
474:     lg.addColorStop(1, 'rgba(255,120,30,0)');
475:     ctx.fillStyle = lg;
476:     ctx.beginPath(); ctx.arc(lx, ly, r, 0, TAU); ctx.fill();
477:   }
478: 
479:   for (const f of fireLights) {
480:     const fx = sxOf(f.x, cx), fy = syOf(f.y, cy);
481:     if (fx < -160 || fx > W + 160 || fy < -160 || fy > H + 160) continue;
482:     const flick = 0.8 + Math.sin(t * 17 + f.seed) * 0.2;
483:     const r = f.r * zoom;
484:     const fg = ctx.createRadialGradient(fx, fy, 0, fx, fy, r);
485:     fg.addColorStop(0, `rgba(255,130,40,${0.17 * flick})`);
486:     fg.addColorStop(0.5, `rgba(255,90,20,${0.06 * flick})`);
487:     fg.addColorStop(1, 'rgba(255,60,0,0)');
488:     ctx.fillStyle = fg;
489:     ctx.beginPath(); ctx.arc(fx, fy, r, 0, TAU); ctx.fill();
490:   }
491: 
492:   // aura de la linterna
493:   const fl = ctx.createRadialGradient(px, py, 0, px, py, 300 * zoom);
494:   fl.addColorStop(0, 'rgba(255,190,110,.045)');
495:   fl.addColorStop(1, 'rgba(255,150,60,0)');
496:   ctx.fillStyle = fl;
497:   ctx.beginPath(); ctx.arc(px, py, 300 * zoom, 0, TAU); ctx.fill();
498: 
499:   // brillo de la munición / botiquín / ácido
500:   for (const pu of pickups) {
501:     if (!inView(pu.x, pu.y, cx, cy, 40)) continue;
502:     const gx = sxOf(pu.x, cx), gy = syOf(pu.y, cy);
503:     const col = pu.type === 'medkit' ? '255,90,80' : pu.type === 'ammo' ? '255,200,90' : pu.type === 'xp' ? '150,255,100' : '255,180,70';
504:     const rg = ctx.createRadialGradient(gx, gy, 0, gx, gy, 22 * zoom);
505:     rg.addColorStop(0, `rgba(${col},.17)`);
506:     rg.addColorStop(1, `rgba(${col},0)`);
507:     ctx.fillStyle = rg;
508:     ctx.beginPath(); ctx.arc(gx, gy, 22 * zoom, 0, TAU); ctx.fill();
509:   }
510:   for (const p of puddles) {
511:     if (!inView(p.x, p.y, cx, cy, 40)) continue;
512:     const gx = sxOf(p.x, cx), gy = syOf(p.y, cy);
513:     const a = clamp(p.life / p.max, 0, 1);
514:     const rg = ctx.createRadialGradient(gx, gy, 0, gx, gy, p.r * 1.6 * zoom);
515:     rg.addColorStop(0, `rgba(120,255,80,${0.07 * a})`);
516:     rg.addColorStop(1, 'rgba(80,200,50,0)');
517:     ctx.fillStyle = rg;
518:     ctx.beginPath(); ctx.arc(gx, gy, p.r * 1.6 * zoom, 0, TAU); ctx.fill();
519:   }
520:   ctx.restore();
521: }
