523: /* ------------------------------------------------------------
524:    Capas superiores
525: ------------------------------------------------------------ */
526: function drawBullets(cx, cy) {
527:   ctx.save();
528:   ctx.globalCompositeOperation = 'lighter';
529:   for (const b of bullets) {
530:     const x = sxOf(b.x, cx), y = syOf(b.y, cy);
531:     if (x < -40 || x > W + 40 || y < -40 || y > H + 40) continue;
532:     const l = hyp(b.vx, b.vy) || 1;
533:     const tx = x - b.vx / l * 17;
534:     const ty = y - b.vy / l * 17;
535:     ctx.strokeStyle = b.color;
536:     ctx.globalAlpha = 0.22;
537:     ctx.lineWidth = 5;
