242:     g.fillRect(b.x, b.y, b.w, b.h);
243:     // borde
244:     g.strokeStyle = '#2a333a';
245:     g.lineWidth = 3;
246:     g.strokeRect(b.x + 1.5, b.y + 1.5, b.w - 3, b.h - 3);
247:     // manchas
248:     for (let i = 0; i < 7; i++) {
249:       g.fillStyle = `rgba(0,0,0,${0.08 + rng() * 0.12})`;
250:       g.beginPath();
251:       g.ellipse(b.x + rng() * b.w, b.y + rng() * b.h, 12 + rng() * 46, 8 + rng() * 28, rng() * TAU, 0, TAU);
252:       g.fill();
253:     }
254:     // juntas del tejado
255:     g.strokeStyle = 'rgba(255,255,255,.035)';
256:     g.lineWidth = 1;
257:     for (let x = b.x + 40; x < b.x + b.w; x += 70) {
258:       g.beginPath(); g.moveTo(x, b.y); g.lineTo(x, b.y + b.h); g.stroke();
259:     }
260:     // equipos de climatización
261:     const units = 1 + (rng() * 3 | 0);
262:     for (let i = 0; i < units; i++) {
263:       const ux = b.x + 22 + rng() * (b.w - 80);
264:       const uy = b.y + 20 + rng() * (b.h - 80);
265:       const uw = 28 + rng() * 26, uh = 20 + rng() * 16;
266:       g.fillStyle = '#0a0e11';
267:       g.fillRect(ux + 3, uy + 3, uw, uh);
268:       g.fillStyle = '#242d33';
269:       g.fillRect(ux, uy, uw, uh);
270:       g.strokeStyle = '#3a454c'; g.lineWidth = 1;
271:       g.strokeRect(ux + 0.5, uy + 0.5, uw - 1, uh - 1);
272:       g.beginPath();
273:       g.arc(ux + uw / 2, uy + uh / 2, Math.min(uw, uh) * 0.3, 0, TAU);
274:       g.stroke();
275:       g.beginPath();
276:       g.moveTo(ux + uw / 2 - 5, uy + uh / 2); g.lineTo(ux + uw / 2 + 5, uy + uh / 2);
277:       g.stroke();
278:     }
279:     // claraboya
280:     if (rng() < 0.55) {
281:       const sx = b.x + 30 + rng() * (b.w - 130);
282:       const sy = b.y + 24 + rng() * (b.h - 90);
283:       const sw = 46 + rng() * 34, sh = 30 + rng() * 20;
284:       const sg = g.createLinearGradient(sx, sy, sx + sw, sy + sh);
285:       sg.addColorStop(0, 'rgba(90,130,145,.18)');
286:       sg.addColorStop(1, 'rgba(30,55,65,.1)');
287:       g.fillStyle = sg;
288:       g.fillRect(sx, sy, sw, sh);
289:       g.strokeStyle = 'rgba(150,190,200,.12)';
290:       g.strokeRect(sx + 0.5, sy + 0.5, sw - 1, sh - 1);
291:       g.beginPath(); g.moveTo(sx + sw / 2, sy); g.lineTo(sx + sw / 2, sy + sh); g.stroke();
292:     }
293:     // tuberías
294:     g.strokeStyle = 'rgba(80,90,95,.18)';
295:     g.lineWidth = 4;
296:     g.beginPath();
297:     g.moveTo(b.x + b.w - 24, b.y + 18);
298:     g.lineTo(b.x + b.w - 24, b.y + b.h - 20);
299:     g.stroke();
300:     // bordillo del tejado
301:     g.fillStyle = 'rgba(0,0,0,.35)';
302:     g.fillRect(b.x, b.y + b.h - 5, b.w, 5);
303:     solids.push({ x: b.x, y: b.y, w: b.w, h: b.h, kind: 'building' });
304:   }
305: }
