421: function drawCar(p) {
422:   const { x, y, w, h, rot, color, seed } = p;
423:   ctx.save();
424:   ctx.translate(x, y);
425:   ctx.rotate(rot);
426:   const rng = mulberry32(seed * 977 + 13);
427:   // ruedas
428:   ctx.fillStyle = '#08090a';
429:   for (const sx of [-w * 0.32, w * 0.32]) {
430:     for (const sy of [-h / 2 + 2, h / 2 - 9]) {
431:       rr(ctx, sx - 9, sy, 18, 7, 3); ctx.fill();
432:     }
433:   }
434:   // carrocería
435:   const gr = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
436:   gr.addColorStop(0, shade(color, 1.35));
437:   gr.addColorStop(0.42, color);
438:   gr.addColorStop(1, shade(color, 0.55));
439:   rr(ctx, -w / 2, -h / 2, w, h, 11);
440:   ctx.fillStyle = gr;
441:   ctx.fill();
442:   ctx.strokeStyle = 'rgba(0,0,0,.55)';
443:   ctx.lineWidth = 2;
444:   ctx.stroke();
445:   // capó / techo
446:   rr(ctx, -w * 0.31, -h * 0.33, w * 0.47, h * 0.66, 6);
447:   ctx.fillStyle = shade(color, 0.72);
448:   ctx.fill();
449:   ctx.strokeStyle = 'rgba(0,0,0,.35)';
450:   ctx.lineWidth = 1;
451:   ctx.stroke();
452:   // parabrisas delantero
453:   ctx.beginPath();
454:   ctx.moveTo(w * 0.17, -h * 0.3);
455:   ctx.lineTo(w * 0.35, -h * 0.21);
456:   ctx.lineTo(w * 0.35, h * 0.21);
457:   ctx.lineTo(w * 0.17, h * 0.3);
458:   ctx.closePath();
459:   ctx.fillStyle = 'rgba(130,175,195,.16)';
460:   ctx.fill();
461:   ctx.strokeStyle = 'rgba(180,215,225,.14)';
462:   ctx.stroke();
463:   // luna trasera
464:   ctx.beginPath();
465:   ctx.moveTo(-w * 0.4, -h * 0.26);
466:   ctx.lineTo(-w * 0.28, -h * 0.3);
467:   ctx.lineTo(-w * 0.28, h * 0.3);
468:   ctx.lineTo(-w * 0.4, h * 0.26);
469:   ctx.closePath();
470:   ctx.fillStyle = 'rgba(110,150,170,.1)';
471:   ctx.fill();
472:   // óxido y golpes
473:   for (let i = 0; i < 6; i++) {
474:     ctx.fillStyle = `rgba(${60 + rng() * 30 | 0},${28 + rng() * 18 | 0},${18 + rng() * 12 | 0},${0.25 + rng() * 0.3})`;
475:     ctx.beginPath();
476:     ctx.ellipse((rng() - 0.5) * w * 0.8, (rng() - 0.5) * h * 0.7, 3 + rng() * 9, 2 + rng() * 5, rng() * TAU, 0, TAU);
477:     ctx.fill();
478:   }
479:   // grieta en el parabrisas
480:   ctx.strokeStyle = 'rgba(200,225,230,.2)';
481:   ctx.lineWidth = 0.8;
482:   ctx.beginPath();
483:   ctx.moveTo(w * 0.24, -h * 0.12);
484:   ctx.lineTo(w * 0.29, -h * 0.02);
485:   ctx.lineTo(w * 0.26, h * 0.09);
486:   ctx.stroke();
487:   // faros
488:   ctx.fillStyle = 'rgba(255,236,190,.4)';
489:   ctx.fillRect(w / 2 - 4, -h * 0.32, 4, 7);
490:   ctx.fillRect(w / 2 - 4, h * 0.24, 4, 7);
491:   ctx.fillStyle = 'rgba(190,40,30,.45)';
492:   ctx.fillRect(-w / 2, -h * 0.32, 3, 6);
493:   ctx.fillRect(-w / 2, h * 0.26, 3, 6);
494:   ctx.restore();
495: }
