546: function drawBarrel(p, t) {
547:   const { x, y, r } = p;
548:   ctx.save();
549:   ctx.translate(x, y);
550:   const gr = ctx.createRadialGradient(-r * 0.35, -r * 0.35, 2, 0, 0, r);
551:   gr.addColorStop(0, p.burning ? '#7d4a25' : '#6a3b2d');
552:   gr.addColorStop(0.6, p.burning ? '#4e2b18' : '#3e2a22');
553:   gr.addColorStop(1, '#1c1512');
554:   ctx.fillStyle = gr;
555:   ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();
556:   ctx.strokeStyle = 'rgba(0,0,0,.55)'; ctx.lineWidth = 2;
557:   ctx.stroke();
558:   ctx.strokeStyle = 'rgba(180,120,70,.24)'; ctx.lineWidth = 1.5;
559:   ctx.beginPath(); ctx.arc(0, 0, r * 0.68, 0, TAU); ctx.stroke();
560:   ctx.beginPath(); ctx.arc(0, 0, r * 0.34, 0, TAU); ctx.stroke();
561:   if (p.burning) {
562:     const f = 0.8 + Math.sin(t * 17 + p.seed) * 0.2;
563:     ctx.globalCompositeOperation = 'lighter';
564:     for (let i = 0; i < 3; i++) {
565:       const a = t * (2.4 + i * 0.3) + p.seed + i * 2.1;
566:       const fx = Math.cos(a) * 4, fy = Math.sin(a) * 4 - 3 - i * 2;
567:       const fg = ctx.createRadialGradient(fx, fy, 0, fx, fy, 11 * f);
568:       fg.addColorStop(0, 'rgba(255,235,160,.9)');
569:       fg.addColorStop(0.4, 'rgba(255,140,30,.5)');
570:       fg.addColorStop(1, 'rgba(255,60,0,0)');
571:       ctx.fillStyle = fg;
572:       ctx.beginPath(); ctx.arc(fx, fy, 11 * f, 0, TAU); ctx.fill();
573:     }
574:     ctx.globalCompositeOperation = 'source-over';
575:   }
576:   ctx.restore();
577: }
