579: function drawBarrier(p) {
580:   const { x, y, w, h, rot } = p;
581:   ctx.save();
582:   ctx.translate(x, y);
583:   ctx.rotate(rot);
584:   ctx.fillStyle = '#3c403c';
585:   rr(ctx, -w / 2, -h / 2, w, h, 3); ctx.fill();
586:   const gr = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
587:   gr.addColorStop(0, '#5a5f58');
588:   gr.addColorStop(0.5, '#454a44');
589:   gr.addColorStop(1, '#2b2f2b');
590:   ctx.fillStyle = gr;
591:   rr(ctx, -w / 2 + 2, -h / 2 + 2, w - 4, h - 4, 2); ctx.fill();
592:   ctx.save();
593:   rr(ctx, -w / 2 + 2, -h / 2 + 2, w - 4, h - 4, 2);
594:   ctx.clip();
595:   ctx.fillStyle = 'rgba(214,120,40,.5)';
596:   for (let i = -2; i < 8; i++) {
597:     ctx.save();
598:     ctx.translate(-w / 2 + i * 16, 0);
599:     ctx.rotate(-0.6);
600:     ctx.fillRect(0, -h, 7, h * 2);
601:     ctx.restore();
602:   }
603:   ctx.restore();
604:   ctx.strokeStyle = 'rgba(0,0,0,.45)'; ctx.lineWidth = 1.5;
605:   rr(ctx, -w / 2, -h / 2, w, h, 3); ctx.stroke();
606:   ctx.restore();
607: }
