609: function drawLamp(p, t) {
610:   const { x, y } = p;
611:   ctx.save();
612:   ctx.translate(x, y);
613:   ctx.fillStyle = '#20262a';
614:   ctx.beginPath(); ctx.arc(0, 0, 7, 0, TAU); ctx.fill();
615:   ctx.strokeStyle = '#39434a'; ctx.lineWidth = 1.5;
616:   ctx.beginPath(); ctx.arc(0, 0, 7, 0, TAU); ctx.stroke();
617:   ctx.strokeStyle = '#2c3439';
618:   ctx.lineWidth = 4;
619:   ctx.beginPath();
620:   ctx.moveTo(0, 0);
621:   ctx.lineTo(10, -12);
622:   ctx.lineTo(16, -14);
623:   ctx.stroke();
624:   const flick = 0.8 + Math.sin(t * 11 + p.seed) * 0.08 + Math.sin(t * 31 + p.seed * 3) * 0.06;
625:   ctx.fillStyle = `rgba(255,210,140,${0.65 * flick})`;
626:   ctx.beginPath(); ctx.arc(17, -15, 4, 0, TAU); ctx.fill();
627:   ctx.restore();
628: }
