630: function drawTree(p) {
631:   const { x, y, seed } = p;
632:   const rng = mulberry32(seed * 331 + 7);
633:   ctx.save();
634:   ctx.translate(x, y);
635:   ctx.strokeStyle = '#171a16';
636:   ctx.lineCap = 'round';
637:   ctx.lineWidth = 7;
638:   ctx.beginPath(); ctx.moveTo(0, 6); ctx.lineTo(0, -12); ctx.stroke();
639:   ctx.lineWidth = 3;
640:   for (let i = 0; i < 6; i++) {
641:     const a = -Math.PI / 2 + (rng() - 0.5) * 2.4;
642:     const len = 14 + rng() * 22;
643:     ctx.beginPath();
644:     ctx.moveTo(0, -10);
645:     ctx.lineTo(Math.cos(a) * len, -10 + Math.sin(a) * len);
646:     ctx.stroke();
647:   }
648:   ctx.fillStyle = '#0d0f0c';
649:   ctx.beginPath(); ctx.arc(0, -11, 4, 0, TAU); ctx.fill();
650:   ctx.restore();
651: }
