656: function buildMenu() {
657:   const rng = mulberry32(99017);
658:   const far = [];
659:   let x = -0.08;
660:   while (x < 1.08) {
661:     const w = 0.035 + rng() * 0.085;
662:     const h = 0.08 + rng() * 0.24;
663:     const wins = [];
664:     const cols = Math.max(2, Math.floor(w * 110));
665:     const rows = Math.max(3, Math.floor(h * 42));
666:     for (let cx = 0; cx < cols; cx++) {
667:       for (let cy = 0; cy < rows; cy++) {
668:         if (rng() < 0.33) {
669:           wins.push({
670:             x: (cx + 0.25) / cols, y: (cy + 0.3) / rows,
